import 'dart:convert';

// A 3 x 2 JPEG, generated locally. Keep real image bytes so editor tests also
// exercise decoding the selected cover rather than accepting a broken image.
final jpegCover = base64Decode(
  '',
);

List<int> mp4Payload({int padding = 0}) => [
  0,
  0,
  0,
  24,
  ...'ftypisom'.codeUnits,
  0,
  0,
  0,
  0,
  ...'isommp42'.codeUnits,
  0,
  0,
  0,
  8,
  ...'mdat'.codeUnits,
  ...List.filled(padding, 1),
];

List<int> croppedMotionPhoto({int padding = 0}) => [
  ...jpegCover,
  ...mp4Payload(padding: padding),
  // Edited files can retain another original/video in their trailer.
  ...jpegCover,
  ...mp4Payload(),
];
